    'twitter': 'https://news.google.com/rss/search?q=%22AndrewYNg%22+OR+%22twitter.com/AndrewYNg%22',
    'linkedin': 'https://news.google.com/rss/search?q=%22linkedin.com/in/andrewyng%22+OR+%22Andrew+Ng+LinkedIn%22',
    'youtube': 'https://news.google.com/rss/search?q=%22Andrew+Ng+YouTube%22+OR+%22youtube.com/user/andrewyantakng%22'
}

counts = {}
for k, url in queries.items():
    feed = feedparser.parse(url)
    counts[k] = len(feed.entries)

print('Mention counts (approx):', counts)

